def convert_open_calls(apps, schema_editor):
    """Events created as registration type "apply" become: applications on (same form, deadline and button text),
    tickets off, date to be announced."""
    Event = apps.get_model('events', 'Event')
    for e in Event.objects.filter(registration_mode='apply'):
        e.applications_enabled = True
        e.application_form_id = e.registration_form_id
        e.applications_close = e.registration_deadline
        e.application_cta = e.cta_label
        e.tickets_enabled = False
        e.date_tba = True
        e.registration_mode = 'form'
        e.registration_form_id = None
        e.registration_deadline = None
        e.cta_label = ''
        e.save()


